-- All practice SQL, for checking in MySQL 8.0+ after loading schema.sql and seed.sql.
-- Generated by tools/build_queries.py.

-- Q1: List the clubs in Area A1, with their city and meeting day.
SELECT club_name, city, meeting_weekday
FROM clubs
WHERE area_id = 'A1'
ORDER BY club_name;

-- Q2: Who are the 10 longest-serving members (earliest first join date)?
SELECT member_id, display_name, first_join_date
FROM members
ORDER BY first_join_date, member_id
LIMIT 10;

-- Q3: How many active members does each club have? (Active = status 'active' and dues paid through 2026-10-31 or later.)
SELECT c.club_name, COUNT(ms.membership_id) AS active_members
FROM clubs c
JOIN memberships ms ON ms.club_id = c.club_id
WHERE ms.status = 'active'
  AND ms.paid_through >= '2026-10-31'
GROUP BY c.club_id, c.club_name
ORDER BY active_members DESC, c.club_name;

-- Q4: Which clubs have fewer than 20 active members and may need support?
SELECT c.club_name, COUNT(ms.membership_id) AS active_members
FROM clubs c
JOIN memberships ms ON ms.club_id = c.club_id
WHERE ms.status = 'active'
  AND ms.paid_through >= '2026-10-31'
GROUP BY c.club_id, c.club_name
HAVING COUNT(ms.membership_id) < 20
ORDER BY active_members, c.club_name;

-- Q5: Which members are still in a club but have not renewed their dues (paid through date is before 2026-10-31)?
SELECT m.display_name, c.club_name, ms.paid_through
FROM memberships ms
JOIN members m ON m.member_id = ms.member_id
JOIN clubs c   ON c.club_id = ms.club_id
WHERE ms.status = 'active'
  AND ms.paid_through < '2026-10-31'
ORDER BY c.club_name, m.display_name;

-- Q6: Show the full role sheet of meeting #1: date, club, standard role name, the name this club uses, and who takes it.
SELECT mt.meeting_date, c.club_name, r.role_name, cr.local_name, m.display_name
FROM role_assignments ra
JOIN meetings mt  ON mt.meeting_id = ra.meeting_id
JOIN clubs c      ON c.club_id = mt.club_id
JOIN roles r      ON r.role_code = ra.role_code
JOIN club_roles cr ON cr.club_id = mt.club_id
                  AND cr.role_code = ra.role_code
JOIN members m    ON m.member_id = ra.member_id
WHERE ra.meeting_id = 1
ORDER BY r.category, r.role_name;

-- Q7: Which active members of Sunrise Speakers Club (club 1) have never taken a meeting role?
SELECT m.member_id, m.display_name
FROM memberships ms
JOIN members m ON m.member_id = ms.member_id
LEFT JOIN role_assignments ra ON ra.member_id = m.member_id
WHERE ms.club_id = 1
  AND ms.status = 'active'
  AND ms.paid_through >= '2026-10-31'
  AND ra.member_id IS NULL
ORDER BY m.display_name;

-- Q8: For each speaker, how many speeches have they given and what is their average length in seconds?
SELECT m.display_name,
       COUNT(*) AS speeches,
       ROUND(AVG(sp.duration_sec), 1) AS avg_sec
FROM speeches sp
JOIN members m ON m.member_id = sp.member_id
WHERE sp.status = 'delivered'
GROUP BY m.member_id, m.display_name
ORDER BY speeches DESC, m.display_name;

-- Q9: Which speakers gave more speeches than the average speaker?
SELECT m.display_name, COUNT(*) AS speeches
FROM speeches sp
JOIN members m ON m.member_id = sp.member_id
WHERE sp.status = 'delivered'
GROUP BY m.member_id, m.display_name
HAVING COUNT(*) > (
    SELECT COUNT(member_id) * 1.0 / COUNT(DISTINCT member_id)
    FROM speeches
    WHERE status = 'delivered'
)
ORDER BY speeches DESC, m.display_name;

-- Q10: Label every October speech as Under time, Qualified, Over time or Not recorded.
SELECT mt.meeting_date, m.display_name, sp.duration_sec,
       sp.min_sec, sp.max_sec,
       CASE
           WHEN sp.duration_sec IS NULL       THEN 'Not recorded'
           WHEN sp.duration_sec < sp.min_sec  THEN 'Under time'
           WHEN sp.duration_sec > sp.max_sec  THEN 'Over time'
           ELSE 'Qualified'
       END AS timing
FROM speeches sp
JOIN meetings mt ON mt.meeting_id = sp.meeting_id
JOIN members m   ON m.member_id = sp.member_id
WHERE mt.meeting_date BETWEEN '2026-10-01' AND '2026-10-31'
  AND sp.status = 'delivered'
ORDER BY mt.meeting_date, sp.speech_id;

-- Q11: For each Pathways path, how many different members have given a speech on it, and how many speeches?
SELECT p.path_name,
       COUNT(DISTINCT sp.member_id) AS members_on_path,
       COUNT(sp.speech_id) AS speeches
FROM pathways p
LEFT JOIN speeches sp ON sp.path_code = p.path_code
                     AND sp.status = 'delivered'
GROUP BY p.path_code, p.path_name
ORDER BY members_on_path DESC, p.path_name;

-- Q12: For each area, how many clubs and how many active members are there?
WITH club_stats AS (
    SELECT c.area_id, c.club_id, COUNT(ms.membership_id) AS active_members
    FROM clubs c
    LEFT JOIN memberships ms
           ON ms.club_id = c.club_id
          AND ms.status = 'active'
          AND ms.paid_through >= '2026-10-31'
    GROUP BY c.area_id, c.club_id
)
SELECT a.area_name, a.division,
       COUNT(cs.club_id) AS clubs,
       SUM(cs.active_members) AS active_members
FROM areas a
JOIN club_stats cs ON cs.area_id = a.area_id
GROUP BY a.area_id, a.area_name, a.division
ORDER BY a.area_id;

-- Q13: Within each club, rank speakers by number of speeches.
WITH counts AS (
    SELECT mt.club_id, sp.member_id, COUNT(*) AS speeches
    FROM speeches sp
    JOIN meetings mt ON mt.meeting_id = sp.meeting_id
    WHERE sp.status = 'delivered'
    GROUP BY mt.club_id, sp.member_id
)
SELECT c.club_name, m.display_name, ct.speeches,
       RANK() OVER (PARTITION BY ct.club_id ORDER BY ct.speeches DESC) AS club_rank
FROM counts ct
JOIN clubs c   ON c.club_id = ct.club_id
JOIN members m ON m.member_id = ct.member_id
ORDER BY c.club_name, club_rank, m.display_name;

-- Q14: Create a view of active memberships, then use it to find members who are active in more than one club.
DROP VIEW IF EXISTS active_memberships;

CREATE VIEW active_memberships AS
SELECT member_id, club_id
FROM memberships
WHERE status = 'active'
  AND paid_through >= '2026-10-31';

SELECT m.display_name, c.club_name
FROM members m
JOIN active_memberships am ON am.member_id = m.member_id
JOIN clubs c ON c.club_id = am.club_id
WHERE EXISTS (
    SELECT 1
    FROM active_memberships x
    WHERE x.member_id = m.member_id
      AND x.club_id <> am.club_id
)
ORDER BY m.display_name, c.club_name;

-- C1 before: INNER JOIN vs LEFT JOIN
SELECT m.display_name, COUNT(ra.role_code) AS roles_taken
FROM memberships ms
JOIN members m ON m.member_id = ms.member_id
JOIN role_assignments ra ON ra.member_id = m.member_id
WHERE ms.club_id = 1 AND ms.status = 'active'
  AND ms.paid_through >= '2026-10-31'
GROUP BY m.member_id, m.display_name
ORDER BY roles_taken DESC, m.display_name;

-- C1 after: INNER JOIN role_assignments → LEFT JOIN role_assignments
SELECT m.display_name, COUNT(ra.role_code) AS roles_taken
FROM memberships ms
JOIN members m ON m.member_id = ms.member_id
LEFT JOIN role_assignments ra ON ra.member_id = m.member_id
WHERE ms.club_id = 1 AND ms.status = 'active'
  AND ms.paid_through >= '2026-10-31'
GROUP BY m.member_id, m.display_name
ORDER BY roles_taken DESC, m.display_name;

-- C2 before: WHERE vs HAVING
SELECT c.club_name, COUNT(ms.membership_id) AS active_members
FROM clubs c
JOIN memberships ms ON ms.club_id = c.club_id
WHERE ms.status = 'active'
  AND ms.paid_through >= '2026-10-31'
GROUP BY c.club_id, c.club_name
HAVING COUNT(ms.membership_id) < 20
ORDER BY active_members, c.club_name;

-- C2 after: Move the COUNT() condition from HAVING into WHERE
SELECT c.club_name, COUNT(ms.membership_id) AS active_members
FROM clubs c
JOIN memberships ms ON ms.club_id = c.club_id
WHERE ms.status = 'active'
  AND ms.paid_through >= '2026-10-31'
  AND COUNT(ms.membership_id) < 20
GROUP BY c.club_id, c.club_name
ORDER BY active_members, c.club_name;

-- C3 before: COUNT(*) vs COUNT(column), AVG vs SUM/COUNT(*)
SELECT COUNT(*) AS all_speeches,
       COUNT(duration_sec) AS timed_speeches,
       ROUND(AVG(duration_sec), 1) AS avg_sec
FROM speeches
WHERE status = 'delivered';

-- C3 after: AVG(duration_sec) → SUM(duration_sec) * 1.0 / COUNT(*)
SELECT COUNT(*) AS all_speeches,
       COUNT(duration_sec) AS timed_speeches,
       ROUND(SUM(duration_sec) * 1.0 / COUNT(*), 1) AS avg_sec
FROM speeches
WHERE status = 'delivered';

-- C4 before: = NULL vs IS NULL
SELECT speech_id, title
FROM speeches
WHERE path_code = NULL
ORDER BY speech_id;

-- C4 after: path_code = NULL → path_code IS NULL
SELECT speech_id, title
FROM speeches
WHERE path_code IS NULL
ORDER BY speech_id;

-- C5 before: RANK() vs DENSE_RANK() vs ROW_NUMBER()
WITH counts AS (
    SELECT sp.member_id, COUNT(*) AS speeches
    FROM speeches sp
    JOIN meetings mt ON mt.meeting_id = sp.meeting_id
    WHERE mt.club_id = 1
      AND sp.status = 'delivered'
    GROUP BY sp.member_id
)
SELECT m.display_name, ct.speeches,
       RANK() OVER (ORDER BY ct.speeches DESC) AS rnk
FROM counts ct
JOIN members m ON m.member_id = ct.member_id
ORDER BY ct.speeches DESC, m.display_name;

-- C5 after: Add DENSE_RANK() and ROW_NUMBER() next to RANK()
WITH counts AS (
    SELECT sp.member_id, COUNT(*) AS speeches
    FROM speeches sp
    JOIN meetings mt ON mt.meeting_id = sp.meeting_id
    WHERE mt.club_id = 1
      AND sp.status = 'delivered'
    GROUP BY sp.member_id
)
SELECT m.display_name, ct.speeches,
       RANK()       OVER (ORDER BY ct.speeches DESC) AS rnk,
       DENSE_RANK() OVER (ORDER BY ct.speeches DESC) AS dense_rnk,
       ROW_NUMBER() OVER (ORDER BY ct.speeches DESC, m.display_name) AS row_num
FROM counts ct
JOIN members m ON m.member_id = ct.member_id
ORDER BY ct.speeches DESC, m.display_name;
